fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            if s.is_empty() {
                // If the input string is empty, produce a vector with one empty string
                vec![String::new()]
            } else if keepends {
                // Retain the line endings by splitting manually
                let mut res = Vec::new();
                let mut start = 0;
                let bytes = s.as_bytes();
                for (i, &b) in bytes.iter().enumerate() {
                    if b == b'\n' {
                        // Include the newline character in the slice
                        res.push(s[start..=i].to_string());
                        start = i + 1;
                    }
                }
                if start < s.len() {
                    // Add final line after last newline
                    res.push(s[start..].to_string());
                }
                if res.is_empty() {
                    // Somehow empty? fallback to vector w/ whole string
                    vec![s]
                } else {
                    res
                }
            } else {
                // Keepends == false, just split on '\n' and drop newline chars
                // split('\n') returns an iterator of string slices without '\n'
                let lines: Vec<String> = s.split('\n').map(|line| line.to_string()).collect();
                if lines.is_empty() {
                    vec![String::new()]
                } else {
                    lines
                }
            }
        })
        .collect()
}